initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Subscription ${subscription} 
        with an id set to ${subscription_id}
        and a linking Entity ${linking_entity}
        with an id set to ${linking_entity_id}
        and a linked Entity ${linked_entity}
        with an id set to ${linked_entity_id}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Entity Attributes with Response Status Code set to 204     and
        Notification with Notification containing entities elements set to 'entity-created-name-attribute-join-flat-simplified.json'
}
